"""Library core: parsing, aggregation and filtering of a plain-text ledger."""

import datetime
import re
from dataclasses import dataclass
from decimal import MAX_EMAX, MAX_PREC, MIN_EMIN, Context, Decimal, ROUND_HALF_EVEN

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(\.[0-9]{1,2})?")
_FIELD_RE = re.compile(r"[ \t]*([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?")

# Exact arithmetic: the default context would round sums at 28 digits.
_EXACT = Context(prec=MAX_PREC, Emax=MAX_EMAX, Emin=MIN_EMIN, rounding=ROUND_HALF_EVEN)
_ZERO = Decimal("0")


class ParseError(ValueError):
    """A line of the ledger is not valid; ``line`` is its 1-based number."""

    def __init__(self, line, reason):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def _parse_line(raw, number):
    """Parse one line (without its newline); return an Entry or None if ignorable."""
    line = raw[:-1] if raw.endswith("\r") else raw
    stripped = line.strip(" \t")
    if not stripped or stripped.startswith("#"):
        return None
    match = _FIELD_RE.fullmatch(line)
    if not match:
        raise ParseError(number, "expected DATE CATEGORY AMOUNT [NOTE]")
    date_text, category, amount_text, note = match.groups()
    if not _DATE_RE.fullmatch(date_text):
        raise ParseError(number, "invalid date %r (expected YYYY-MM-DD)" % date_text)
    try:
        date = datetime.date(int(date_text[:4]), int(date_text[5:7]), int(date_text[8:]))
    except ValueError:
        raise ParseError(number, "date %s does not exist" % date_text) from None
    if not _AMOUNT_RE.fullmatch(amount_text):
        raise ParseError(
            number,
            "invalid amount %r (optional sign, at most two decimals)" % amount_text,
        )
    return Entry(date, category.lower(), Decimal(amount_text), (note or "").strip(" \t"))


def parse(text):
    """Parse ledger text into a list of Entry, in order; raise ParseError on a bad line."""
    entries = []
    for number, raw in enumerate(text.split("\n"), 1):
        entry = _parse_line(raw, number)
        if entry is not None:
            entries.append(entry)
    return entries


def _add(a, b):
    return _EXACT.add(a, b)


def balance(entries):
    """Total of all amounts (Decimal zero for no entries)."""
    total = _ZERO
    for entry in entries:
        total = _add(total, entry.amount)
    return total


def _group(entries, key):
    totals = {}
    for entry in entries:
        k = key(entry)
        totals[k] = _add(totals.get(k, _ZERO), entry.amount)
    return totals


def by_category(entries):
    """Dict of category -> total, in order of first appearance."""
    return _group(entries, lambda e: e.category)


def by_month(entries):
    """Dict of "YYYY-MM" -> total, in order of first appearance."""
    return _group(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def filter_entries(entries, category=None, since=None, until=None):
    """Entries matching all given filters, in the order given (None = no filter)."""
    wanted = category.lower() if category is not None else None
    result = []
    for entry in entries:
        if wanted is not None and entry.category.lower() != wanted:
            continue
        if since is not None and entry.date < since:
            continue
        if until is not None and entry.date > until:
            continue
        result.append(entry)
    return result
