import argparse
import csv
import datetime
import io
import json
import os
import sys
from decimal import Decimal

from .ledger import (
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    parse,
)

_VALUE_OPTIONS = ("--category", "--since", "--until", "--by", "--format")


def money(value):
    """Format with exactly two decimals, '-' for negatives, no '+' or separators."""
    if value == 0:
        value = Decimal(0)  # no "-0.00"
    return format(value, ".2f")


def entry_line(entry):
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, money(entry.amount))
    return line + " " + entry.note if entry.note else line


def _date_arg(text):
    try:
        if len(text) != 10 or not text.isascii() or text[4] != "-" or text[7] != "-":
            raise ValueError(text)
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        raise argparse.ArgumentTypeError("invalid date %r (expected YYYY-MM-DD)" % text)


def _read_text(path):
    if path == "-":
        stream = sys.stdin
        data = stream.buffer.read() if hasattr(stream, "buffer") else stream.read()
    else:
        with open(path, "rb") as handle:
            data = handle.read()
    if isinstance(data, bytes):
        data = data.decode("utf-8-sig")
    elif data.startswith("﻿"):
        data = data[1:]
    return data


def _load(args):
    return parse(_read_text(args.file))


def _sorted_entries(args):
    entries = filter_entries(
        _load(args), category=args.category, since=args.since, until=args.until
    )
    return sorted(entries, key=lambda e: e.date)  # stable: same day keeps file order


def _dump(obj):
    return json.dumps(obj) + "\n"


def cmd_balance(args):
    total = money(balance(_load(args)))
    return _dump({"balance": total}) if args.json else total + "\n"


def cmd_summary(args):
    group = by_month if args.by == "month" else by_category
    totals = {name: money(total) for name, total in group(_load(args)).items()}
    names = sorted(totals)
    if args.json:
        return _dump({name: totals[name] for name in names})
    return "".join("%s  %s\n" % (name, totals[name]) for name in names)


def cmd_list(args):
    entries = _sorted_entries(args)
    if args.json:
        return _dump(
            [
                {
                    "date": e.date.isoformat(),
                    "category": e.category,
                    "amount": money(e.amount),
                    "note": e.note,
                }
                for e in entries
            ]
        )
    return "".join(entry_line(e) + "\n" for e in entries)


def cmd_export(args):
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in _sorted_entries(args):
        writer.writerow([e.date.isoformat(), e.category, money(e.amount), e.note])
    return buffer.getvalue()


def cmd_add(args):
    fields = [args.date, args.category, args.amount]
    if any(not f or any(c in f for c in " \t\r\n") for f in fields) or any(
        c in args.note for c in "\r\n"
    ):
        raise ParseError(1, "date, category and amount must be single words; note one line")
    entry = parse(" ".join(fields + [args.note]))[0]
    line = entry_line(entry)
    payload = (line + "\n").encode("utf-8", "strict") if _encodable(line) else None
    if payload is None:
        raise ParseError(1, "entry is not valid UTF-8 text")
    with open(args.file, "ab+") as handle:
        handle.seek(0, os.SEEK_END)
        if handle.tell() > 0:
            handle.seek(-1, os.SEEK_END)
            if handle.read(1) != b"\n":
                payload = b"\n" + payload
        handle.write(payload)
    return line + "\n"


def _encodable(text):
    try:
        text.encode("utf-8")
    except UnicodeEncodeError:
        return False
    return True


def _build_parser():
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Report where the money went from a plain-text ledger."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND", required=True)

    def command(name, func, help_, with_file=True):
        p = sub.add_parser(name, help=help_, description=help_, allow_abbrev=False)
        p.set_defaults(func=func)
        if with_file:
            p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
        return p

    p = command("balance", cmd_balance, "print the total of all amounts")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("summary", cmd_summary, "print totals per category or month")
    p.add_argument("--by", choices=("category", "month"), default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    def filters(p):
        p.add_argument("--category", help="only this category (any case)")
        p.add_argument("--since", type=_date_arg, metavar="DATE", help="from DATE (YYYY-MM-DD)")
        p.add_argument("--until", type=_date_arg, metavar="DATE", help="up to DATE (YYYY-MM-DD)")

    p = command("list", cmd_list, "print entries, oldest first")
    filters(p)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("export", cmd_export, "print entries as CSV")
    filters(p)
    p.add_argument("--format", choices=("csv",), default="csv")

    p = command("add", cmd_add, "append an entry to FILE", with_file=False)
    p.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
