def _prepare(argv):
    """Let option values and add's arguments start with a dash (e.g. -abc, -x)."""
    if argv and argv[0] == "add":
        rest = argv[1:]
        if rest and rest[0] not in ("--", "-h", "--help"):
            return ["add", "--"] + rest
        return argv
    out = []
    i = 0
    while i < len(argv):
        token = argv[i]
        if token == "--":
            out.extend(argv[i:])
            break
        if token in _VALUE_OPTIONS and i + 1 < len(argv):
            out.append(token + "=" + argv[i + 1])
            i += 2
            continue
        out.append(token)
        i += 1
    return out


def _fail(message, code):
    try:
        sys.stderr.write("pennywise: %s\n" % message)
    except Exception:
        pass
    return code


def _emit(text):
    try:
        sys.stdout.write(text)
        sys.stdout.flush()
    except BrokenPipeError:
        _discard_stdout()
    except OSError as exc:
        _discard_stdout()
        return _fail("cannot write output: %s" % (exc.strerror or exc), 2)
