def _discard_stdout():
    """Point stdout at /dev/null so a failed flush is not retried at exit."""
    try:
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    try:
        args = _build_parser().parse_args(_prepare(argv))
    except SystemExit as exc:
        code = exc.code
        return code if isinstance(code, int) else (0 if code is None else 2)
    try:
        text = args.func(args)
    except ParseError as exc:
        return _fail(str(exc), 1)
    except UnicodeDecodeError as exc:
        return _fail("%s is not valid UTF-8" % ("standard input" if args.file == "-" else args.file), 2)
    except OSError as exc:
        return _fail("cannot access %s: %s" % (args.file, exc.strerror or exc), 2)
    return _emit(text)
